#!/usr/bin/env python3
"""Compare the bindings generated by jextract for the same OS on two CPUs.

jextract writes each header class in several files (e.g. glx_h, glx_h_1, ...) chained by
inheritance, so that a declaration only present on one CPU shifts all the following
declarations to other files. Each package is hence compared as a single stream made of its
files in name order, in which the numbered header classes are renamed to their header class.

The report lists, for each package :
* the declarations (functions, constants, structs, ...) only generated for one CPU,
* the declarations generated for both CPUs with a different code (layout, descriptor, value),
* among them, the ones that the PanamaGL sources given with --uses refer to.

Usage :
  compare_bindings.py <bindings of CPU a> <bindings of CPU b> --labels x64 arm64
                      --uses <java source dir>... --output report.md
"""

import argparse
import difflib
import re
import sys
from pathlib import Path

# Start of a declaration of a header class : the first name followed by "(", "=" or "{" on
# a line indented once, e.g. "private static class glXChooseVisual {",
# "public static FunctionDescriptor glXChooseVisual$descriptor() {", "public static int GLX_RGBA() {"
DECLARATION = re.compile(r'([A-Za-z_]\w*)(?:\$\w+)?\s*[(={]')

IDENTIFIER = re.compile(r'\b[A-Za-z_]\w*\b')


def header_classes(package_dir):
  """Header classes are written in several files, e.g. glx_h, glx_h_1, glx_h_2 and glx_h$shared."""
  names = {f.stem for f in package_dir.glob('*.java')}
  return sorted({n for n in names if (n + '_1') in names or (n + '$shared') in names},
                key=len, reverse=True)


def sort_key(path):
  """Name order, numbered header classes in numeric order."""
  match = re.match(r'(.*?)_(\d+)$', path.stem)
  return (match.group(1), int(match.group(2))) if match else (path.stem, -1)


def stream(package_dir):
  """The declarations of a package, as a dict name -> code, in file order.

  A file declaring a struct, union, typedef or function pointer is one declaration. A header
  class is cut in declarations of functions, variables, constants and layouts, each with the
  documentation preceding it.
  """
  headers = header_classes(package_dir)
  header_file = re.compile(r'^(' + '|'.join(map(re.escape, headers)) + r')(_\d+|\$shared)?$') \
    if headers else None
  renaming = re.compile(r'\b(' + '|'.join(map(re.escape, headers)) + r')_\d+\b') \
    if headers else None
  declarations = {}

  def add(name, lines):
    declarations.setdefault(name, []).extend(lines)

  for f in sorted(package_dir.glob('*.java'), key=sort_key):
    # The closing brace of a header class file would belong to its last declaration, which depends
    # on how the header class is split in files
    lines = [line for line in f.read_text(encoding='utf-8', errors='replace').splitlines()
             if line.strip() and not line.startswith(('import ', 'package ')) and line != '}']
    if renaming:
      lines = [renaming.sub(r'\1', line) for line in lines]
    if not (header_file and header_file.match(f.stem)):
      add(f.stem, lines)
      continue
    current, pending = None, []
    for line in lines:
      code = line.strip()
      if code.startswith(('/*', '*')):
        pending.append(line)
        continue
      if line.startswith('    ') and not line.startswith('     ') and not code.startswith('}'):
        match = DECLARATION.search(code)
        if match and match.group(1) not in headers:
          current = match.group(1)
      if current is not None:
        add(current, pending + [line])
      pending = []
  return {name: '\n'.join(code) for name, code in declarations.items()}


def packages(root):
  return sorted({f.parent.relative_to(root) for f in root.rglob('*.java')})


def used_identifiers(source_dirs):
  used = set()
  for d in source_dirs:
    for f in Path(d).rglob('*.java'):
      used.update(IDENTIFIER.findall(f.read_text(encoding='utf-8', errors='replace')))
  return used


def compare(dir_a, dir_b, label_a, label_b, used, max_diff_lines):
  out = []
  summary = []
  all_packages = sorted(set(packages(dir_a)) | set(packages(dir_b)))
  for package in all_packages:
    a = stream(dir_a / package) if (dir_a / package).is_dir() else {}
    b = stream(dir_b / package) if (dir_b / package).is_dir() else {}
    only_a = [n for n in a if n not in b]
    only_b = [n for n in b if n not in a]
    different = [n for n in a if n in b and a[n] != b[n]]
    same = sum(1 for n in a if n in b and a[n] == b[n])
    used_diff = sorted(n for n in set(only_a) | set(only_b) | set(different) if n in used)
    summary.append((str(package).replace('/', '.'), len(a), len(b), same, len(only_a),
                    len(only_b), len(different), used_diff))

    out.append(f'\n## Package `{package}`\n')
    out.append(f'{len(a)} declarations for {label_a}, {len(b)} for {label_b}, {same} identical.\n')
    for title, names in ((f'Only for {label_a}', only_a), (f'Only for {label_b}', only_b),
                         ('Different', different)):
      out.append(f'\n### {title} ({len(names)})\n')
      if names:
        out.append(', '.join(f'**`{n}`**' if n in used else f'`{n}`' for n in names) + '\n')
    if used_diff:
      out.append(f'\n### Used by PanamaGL and not identical ({len(used_diff)})\n')
      out.append(', '.join(f'`{n}`' for n in used_diff) + '\n')
    if different:
      out.append(f'\n### Diff of the different declarations\n\n```diff')
      lines = 0
      for n in different:
        diff = list(difflib.unified_diff(a[n].splitlines(), b[n].splitlines(),
                                         f'{label_a}/{n}', f'{label_b}/{n}', lineterm='', n=1))
        if lines + len(diff) > max_diff_lines:
          out.append(f'... (diff truncated after {lines} lines)')
          break
        out.extend(diff)
        lines += len(diff)
      out.append('```\n')

  header = [f'# Bindings generated on {label_a} vs {label_b}\n',
            f'| Package | {label_a} | {label_b} | Identical | Only {label_a} | Only {label_b} '
            f'| Different | Used by PanamaGL and not identical |',
            '|---|---|---|---|---|---|---|---|']
  for p, na, nb, same, oa, ob, diff, used_diff in summary:
    header.append(f'| `{p}` | {na} | {nb} | {same} | {oa} | {ob} | {diff} | '
                  f'{", ".join(f"`{n}`" for n in used_diff) or "none"} |')
  identical = all(oa == 0 and ob == 0 and diff == 0 for _, _, _, _, oa, ob, diff, _ in summary)
  safe = all(not used_diff for *_, used_diff in summary)
  verdict = ('**Identical bindings.**' if identical else
             '**Bindings differ, but not on any declaration used by PanamaGL.**' if safe else
             '**Bindings differ on declarations used by PanamaGL.**')
  return '\n'.join(header) + f'\n\n{verdict}\n' + '\n'.join(out), identical, safe


def main():
  parser = argparse.ArgumentParser(description=__doc__,
                                   formatter_class=argparse.RawDescriptionHelpFormatter)
  parser.add_argument('a', type=Path)
  parser.add_argument('b', type=Path)
  parser.add_argument('--labels', nargs=2, default=['a', 'b'])
  parser.add_argument('--uses', nargs='*', default=[])
  parser.add_argument('--output', type=Path)
  parser.add_argument('--max-diff-lines', type=int, default=4000)
  args = parser.parse_args()

  report, identical, safe = compare(args.a, args.b, *args.labels, used_identifiers(args.uses),
                                    args.max_diff_lines)
  if args.output:
    args.output.write_text(report, encoding='utf-8')
  print(report)
  return 0


if __name__ == '__main__':
  sys.exit(main())
